body:
Apparently there's a problem with `empty()` calls on the results of array access calls on mixed variables. I can't quite point the finger on it, but I don't think _any_ of the following should report any errors, but some do (see inline/dockblock comments):
```php
<?php
// results in two PossiblyUndefinedVariable in if conditions
function a(array $in): void
{
    $r = [];
    foreach ($in as $entry) {
        if (!empty($entry['a'])) {
            $r[] = [];
        }
        if (empty($entry['a'])) {
            $r[] = [];
        }
    }
}

// results in one PossiblyUndefinedVariable (second if condition)
function b(array $in): void
{
    $i = 0;
    foreach ($in as $entry) {
        if (!empty($entry['a'])) {
            $i--;
        }
        if (empty($entry['a'])) {
            $i++;
        }
    }
}

/**
 * results in one PossiblyUndefinedVariable (second if)
 */
function c(array $in): void
{
    foreach ($in as $entry) {
        if (!empty($entry['a'])) {}
    }
    foreach ($in as $entry) {
        if (empty($entry['a'])) {}
    }
}

/**
 * results in NO problems
 */
function d(array $in): void
{
    foreach ($in as $entry) {
        if (empty($entry['a'])) {}
    }
}

/**
 * NO problems either
 */
function e(array $in): void
{
    foreach ($in as $entry) {
        if (!empty($entry['a'])) {}
    }
}

/**
 * Results in one PossiblyUndefinedVariable (second if)
 */
function f(array $in): void
{
    $entry = reset($in);
    if (!empty($entry['a'])) {}
    if (empty($entry['a'])) {}
}

/**
 * Results in one PossiblyUndefinedVariable (second if)
 * @param mixed $in
 */
function g($in): void
{
    if (!empty($in['a'])) {}
    if (empty($in['a'])) {}
}

/**
 * NO problems reported here
 * @param mixed $in
 */
function h($in): void
{
    if (isset($in['a']) && $in['a']) {}
    if (!isset($in['a']) || !$in['a']) {}
}
```
